package gg.aetherfall.core.module;

import gg.aetherfall.core.AetherCore;
import gg.aetherfall.core.economy.Eco;
import gg.aetherfall.core.util.Text;
import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabExecutor;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;
import org.jetbrains.annotations.NotNull;

import java.io.File;
import java.io.IOException;
import java.util.*;

/** Lightweight persistent guilds/towns foundation with shared levels and invitations. */
public final class Guilds implements TabExecutor {
    private static final class Guild { final String name; final UUID owner; final Set<UUID> members; int points; Guild(String name, UUID owner, Set<UUID> members, int points) { this.name = name; this.owner = owner; this.members = members; this.points = points; } }
    private final AetherCore plugin; private final File file; private final Map<String, Guild> guilds = new HashMap<>(); private final Map<UUID, String> invites = new HashMap<>(); private final Map<UUID, Long> contributionCooldowns = new HashMap<>();
    public Guilds(AetherCore plugin) { this.plugin = plugin; file = new File(plugin.getDataFolder(), "guilds.yml"); load(); }
    private void load() { YamlConfiguration y = YamlConfiguration.loadConfiguration(file); for (String key : y.getStringList("names")) { String path = "guilds." + key; UUID owner; try { owner = UUID.fromString(y.getString(path + ".owner")); } catch (Exception e) { continue; } Set<UUID> members = new HashSet<>(); for (String raw : y.getStringList(path + ".members")) try { members.add(UUID.fromString(raw)); } catch (Exception ignored) {} guilds.put(key.toLowerCase(Locale.ROOT), new Guild(key, owner, members, y.getInt(path + ".points"))); } }
    private void save() { YamlConfiguration y = new YamlConfiguration(); y.set("names", guilds.values().stream().map(g -> g.name).toList()); for (Guild g : guilds.values()) { String path = "guilds." + g.name; y.set(path + ".owner", g.owner.toString()); y.set(path + ".members", g.members.stream().map(UUID::toString).toList()); y.set(path + ".points", Math.max(0, g.points)); } File temp = new File(file.getParentFile(), file.getName() + ".tmp"); try { y.save(temp); try { java.nio.file.Files.move(temp.toPath(), file.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING, java.nio.file.StandardCopyOption.ATOMIC_MOVE); } catch (java.nio.file.AtomicMoveNotSupportedException e) { java.nio.file.Files.move(temp.toPath(), file.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING); } } catch (IOException e) { if (temp.exists()) temp.delete(); plugin.getLogger().warning("Could not save guilds: " + e.getMessage()); } }
    private Guild guild(Player p) { return guilds.values().stream().filter(g -> g.members.contains(p.getUniqueId())).findFirst().orElse(null); }
    private Guild find(String name) { return guilds.get(name.toLowerCase(Locale.ROOT)); }
    private int level(Guild g) { return g.points / 1000 + 1; }
    public void open(Player p) { Guild g = guild(p); if (g == null) p.sendMessage(Text.mm("<aqua><bold>Guilds</bold></aqua> <gray>Create one with <yellow>/guild create <name>")); else p.sendMessage(Text.mm("<aqua><bold>Guild " + g.name + "</bold></aqua> <gray>Level " + level(g) + " · " + g.members.size() + " members · " + g.points + " contribution points")); }
    @Override public boolean onCommand(@NotNull CommandSender s, @NotNull Command c, @NotNull String l, String @NotNull [] a) { if (!(s instanceof Player p)) return true; String sub = a.length == 0 ? "info" : a[0].toLowerCase(Locale.ROOT); Guild own = guild(p); switch (sub) { case "create" -> { if (own != null || a.length < 2) { p.sendMessage(Text.mm("<red>Usage: /guild create <name> (you must not already belong to one)")); return true; } String name = a[1]; if (!name.matches("[A-Za-z0-9_-]{3,16}") || find(name) != null) { p.sendMessage(Text.mm("<red>That guild name is unavailable. Use 3-16 letters, numbers, _ or -.</red>")); return true; } Set<UUID> members = new HashSet<>(); members.add(p.getUniqueId()); guilds.put(name.toLowerCase(Locale.ROOT), new Guild(name, p.getUniqueId(), members, 0)); plugin.data().recordFunnel(p, "first_guild"); save(); p.sendMessage(Text.mm("<green>Guild created: <aqua>" + name)); } case "invite" -> { if (own == null || !own.owner.equals(p.getUniqueId()) || a.length < 2) { p.sendMessage(Text.mm("<red>Only the guild owner can invite players.")); return true; } Player target = Bukkit.getPlayerExact(a[1]); if (target == null) { p.sendMessage(Text.mm("<red>That player is not online.")); return true; } invites.put(target.getUniqueId(), own.name); target.sendMessage(Text.mm("<aqua>You were invited to <white>" + own.name + "</white>. Use <yellow>/guild join " + own.name)); } case "join" -> { if (own != null || a.length < 2 || !ownInvite(p, a[1])) { p.sendMessage(Text.mm("<red>You need a valid guild invitation.")); return true; } Guild target = find(a[1]); target.members.add(p.getUniqueId()); invites.remove(p.getUniqueId()); plugin.data().recordFunnel(p, "first_guild"); save(); p.sendMessage(Text.mm("<green>You joined <aqua>" + target.name)); } case "leave" -> { if (own == null) return true; own.members.remove(p.getUniqueId()); if (own.members.isEmpty() || own.owner.equals(p.getUniqueId())) guilds.remove(own.name.toLowerCase(Locale.ROOT)); save(); p.sendMessage(Text.mm("<gray>You left your guild.")); } case "contribute" -> { if (own == null) { p.sendMessage(Text.mm("<red>Join a guild first.")); return true; } long now = System.currentTimeMillis(); long cooldown = Math.max(0L, plugin.getConfig().getLong("guilds.contribution-cooldown-seconds", 30L)) * 1000L; long last = contributionCooldowns.getOrDefault(p.getUniqueId(), 0L); if (now - last < cooldown) { long left = Math.max(1L, (cooldown - (now - last) + 999L) / 1000L); p.sendMessage(Text.mm("<gray>Contribute again in <yellow>" + left + "s</yellow>.")); return true; } double cost = Math.max(0.0, plugin.getConfig().getDouble("guilds.contribution-cost", 100.0)); if (!Eco.withdraw(p, cost)) { p.sendMessage(Text.mm("<red>You need <gold>" + Eco.fmt(cost) + " coins</gold> to contribute.")); return true; } contributionCooldowns.put(p.getUniqueId(), now); own.points = Math.min(Integer.MAX_VALUE, own.points + 10); plugin.community().progress(p, 10); save(); p.sendMessage(Text.mm("<green>Guild contribution added for <gold>" + Eco.fmt(cost) + " coins</gold>. Level: " + level(own))); } default -> open(p); } return true; }
    private boolean ownInvite(Player p, String name) { return name.equalsIgnoreCase(invites.get(p.getUniqueId())); }
    @Override public List<String> onTabComplete(@NotNull CommandSender s, @NotNull Command c, @NotNull String l, String @NotNull [] a) { return a.length == 1 ? List.of("create", "invite", "join", "leave", "contribute", "info") : List.of(); }
}
